    // ─────────── فصل ۱: برج ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Tower", titlePersian = "برج",
        paragraphs = listOf(
            StoryParagraph("It was the morning of June 16, 1904, in the city of Dublin, and a young man named Stephen Dedalus stood at the top of a stone tower overlooking the sea.", "صبح ۱۶ ژوئن ۱۹۰۴، در شهر دوبلین بود و جوانی به نام استیون ددالوس در بالای برجی سنگی ایستاده بود و به دریا می‌نگریست."),
            StoryParagraph("The tower was called Martello, one of many such towers the English had built along the Irish coast to defend against Napoleon, who never came.", "برج مارتلو نامیده می‌شد، یکی از بسیاری از چنین برج‌هایی که انگلیسی‌ها در طول ساحل ایرلند ساخته بودند تا از ناپلئون دفاع کنند، که هرگز نیامد."),
            StoryParagraph("Stephen lived in the tower with two companions: Buck Mulligan, a medical student, and Haines, an Englishman who had come to Ireland to study its culture.", "استیون در برج با دو همراه زندگی می‌کرد: باک مولگان، دانشجوی پزشکی و هینز، انگلیسی‌ای که به ایرلند آمده بود تا فرهنگش را مطالعه کند."),
            StoryParagraph("Buck Mulligan was a large, ruddy man with a mocking tongue and a great appetite for life; he had saved Stephen from himself more than once, and had mocked him every time.", "باک مولگان مردی بزرگ و سرخ‌رو بود با زبانی ریشخندآمیز و اشتهایی فراوان به زندگی؛ بیش از یک بار استیون را از خودش نجات داده بود و هر بار مسخره‌اش کرده بود."),
            StoryParagraph("Haines was quiet and polite, but Stephen did not trust him; there was something in the Englishman's calm that seemed to Stephen to be a kind of conquest.", "هینز ساکت و مؤدب بود اما استیون به او اعتماد نداشت؛ چیزی در آرامش آن انگلیسی بود که به نظر استیون نوعی فتح به نظر می‌رسید."),
            StoryParagraph("The morning light was clear and cool; the sea stretched out to the horizon, grey-green and calm.", "نور صبح واضح و خنک بود؛ دریا تا افق کشیده شده بود، خاکستری-سبز و آرام."),
            StoryParagraph("Mulligan came up the stairs with a shaving bowl, reciting the Latin words of the Mass, mocking the Church he had abandoned.", "مولگان با کاسه‌ای برای اصلاح از پله‌ها بالا آمد، کلمات لاتین مراسم عشای ربانی را می‌خواند و کلیسایی را که ترک کرده بود مسخره می‌کرد."),
            StoryParagraph("'Introibo ad altare Dei,' he sang, and laughed at his own performance, and asked Stephen if he was not afraid of the thunder of God's wrath.", "خواند: «به سوی محراب خدا می‌آیم.» و به خودنمایی‌اش خندید و از استیون پرسید از رعد خشم خدا نمی‌ترسد."),
            StoryParagraph("Stephen did not answer; he was thinking about his mother, who had died the year before, and about her dying wish that he would pray for her.", "استیون پاسخ نداد؛ به مادرش فکر می‌کرد که سال قبل مرده بود و به آرزوی در حال مرگش که برایش دعا کند."),
            StoryParagraph("He had refused to kneel, had refused to pray, had refused to pretend a faith he did not feel; and her ghost haunted him for it.", "امتناع کرده بود از زانو زدن، از دعا کردن، از تظاهر به ایمانی که حس نمی‌کرد؛ و شبحش برای این تسخیرش می‌کرد."),
            StoryParagraph("'You could have knelt,' Mulligan said. 'You could have made her happy. It would not have cost you anything.'", "مولگان گفت: «می‌توانستی زانو بزنی. می‌توانستی خوشحالش کنی. چیزی برایت هزینه نداشت.»"),
            StoryParagraph("'I could not,' Stephen said. 'I could not pretend. Not even for her.'", "استیون گفت: «نمی‌توانستم. نمی‌توانستم تظاهر کنم. حتی برای او.»"),
            StoryParagraph("'You are a strange one, Dedalus,' Mulligan said. 'You have the soul of a Jesuit and the mind of a heretic. You will never find peace.'", "مولگان گفت: «عجیبی، ددالوس. روح یسوعی و ذهن یک بدعت‌گذار داری. هرگز آرامش نمی‌یابی.»"),
            StoryParagraph("'Perhaps not,' Stephen said. 'Perhaps peace is not what I am seeking.'", "استیون گفت: «شاید نه. شاید آرامش آن چیزی نیست که در جستجویش هستم.»"),
            StoryParagraph("They ate breakfast together on the roof of the tower, looking out over the sea.", "با هم روی بام برج صبحانه خوردند و به دریا نگاه کردند."),
            StoryParagraph("An old woman came up the stairs, a milkwoman, delivering milk to the men in the tower.", "زنی پیر از پله‌ها بالا آمد، زنی شیرفروش، که برای مردان برج شیر می‌آورد."),
            StoryParagraph("Stephen watched her, and thought about Ireland: an old woman, poor, oppressed, serving those who ruled her.", "استیون تماشایش کرد و به ایرلند فکر کرد: پیرزنی، فقیر، ستمدیده، در خدمت کسانی که بر او حکومت می‌کردند."),
            StoryParagraph("'We are all her servants,' he thought. 'Mulligan, Haines, myself. We serve an empire, a church, a history that is not our own.'", "فکر کرد: «همه‌مان خدمتگزار اوییم. مولگان، هینز، خودم. در خدمت امپراتوری، کلیسا، تاریخی که مال خودمان نیست.»"),
            StoryParagraph("Mulligan paid for the milk, and asked the woman if she had brought the bill for the tower.", "مولگان پول شیر را داد و از زن پرسید صورت‌حساب برج را آورده."),
            StoryParagraph("'I have not,' she said. 'I will bring it next time.'", "گفت: «نیاورده‌ام. بار بعد می‌آورم.»"),
            StoryParagraph("'Ah,' Mulligan said, 'and when will that be? When the French come?'", "مولگان گفت: «آه، آن وقت کِی است؟ وقتی فرانسوی‌ها بیایند؟»"),
            StoryParagraph("They laughed, the three men, at the old woman and her poverty, and Stephen felt a pang of shame.", "خندیدند، آن سه مرد، به پیرزن و فقرش و استیون دردی از شرم حس کرد."),
            StoryParagraph("'They are making me complicit,' he thought. 'They are making me part of their contempt.'", "فکر کرد: «مرا شریک می‌کنند. مرا بخشی از تحقیرشان می‌کنند.»"),
            StoryParagraph("After breakfast, Mulligan and Haines went down to swim in the sea, and Stephen stayed behind.", "بعد از صبحانه، مولگان و هینز برای شنا در دریا پایین رفتند و استیون عقب ماند."),
            StoryParagraph("He watched them from the parapet, diving into the cold water, laughing and shouting like boys.", "از کنگره برج تماشایشان کرد که در آب سرد شیرجه می‌زنند، مثل پسرها می‌خندند و فریاد می‌زنند."),
            StoryParagraph("'Usurpers,' he thought. 'They have taken my tower, my home, my country. And I let them.'", "فکر کرد: «غاصبان. برج مرا گرفته‌اند، خانه‌ام، کشورم. و من گذاشتم.»"),
            StoryParagraph("He thought about his father, Simon Dedalus, an actor, a drinker, a man of charm and weakness.", "به پدرش فکر کرد، سایمون ددالوس، بازیگر، میگسار، مردی با جذابیت و ضعف."),
            StoryParagraph("He thought about his mother, May Dedalus, a woman of faith and sorrow, who had died of cancer while Stephen refused to pray.", "به مادرش فکر کرد، می ددالوس، زنی با ایمان و اندوه، که از سرطان مرده بود در حالی که استیون از دعا امتناع کرده بود."),
            StoryParagraph("He thought about his country, Ireland, the 'old sow that eats her farrow,' as he had once called her in a moment of anger.", "به کشورش فکر کرد، ایرلند، «خوک پیری که بچه‌هایش را می‌خورد»، همانطور که روزی در لحظه‌ای از خشم نامیده بود."),
            StoryParagraph("He thought about his art, his writing, his ambition to forge in the smithy of his soul the uncreated conscience of his race.", "به هنرش فکر کرد، به نوشتنش، به جاه‌طلبی‌اش که در آهنگری روحش وجدان ناآفریده نژادش را بسازد."),
            StoryParagraph("And he felt, in that moment, the full weight of his exile: exile from faith, exile from family, exile from country, exile from self.", "و در آن لحظه وزن کامل تبعیدش را حس کرد: تبعید از ایمان، از خانواده، از کشور، از خود."),
            StoryParagraph("Mulligan and Haines came back up the stairs, dripping and laughing, and Mulligan mocked Stephen for not having joined them.", "مولگان و هینز از پله‌ها بالا آمدند، چکه‌کنان و خندان و مولگان استیون را مسخره کرد که به آن‌ها نپیوسته بود."),
            StoryParagraph("'You are afraid of the water,' he said. 'You are afraid of everything.'", "گفت: «از آب می‌ترسی. از همه چیز می‌ترسی.»"),
            StoryParagraph("'I am not afraid,' Stephen said. 'I simply do not wish to be like you.'", "استیون گفت: «نمی‌ترسم. تنها نمی‌خواهم مثل تو باشم.»"),
            StoryParagraph("The words hung in the air, and Mulligan was silent for a moment, and then he laughed, and then he turned away.", "کلمات در هوا ماندند و مولگان لحظه‌ای ساکت شد و بعد خندید و بعد روی برگرداند."),
            StoryParagraph("Stephen took his ashplant, his walking stick, and he left the tower, and he did not look back.", "استیون عصایش را برداشت، چوب‌دستی‌اش و برج را ترک کرد و عقب نگاه نکرد."),
            StoryParagraph("He walked along the road by the sea, and he thought about the day ahead, and he thought about the man he would meet that evening, a man named Leopold Bloom.", "در جاده کنار دریا قدم زد و به روز پیش رو فکر کرد و به مردی که آن عصر ملاقاتش می‌کرد، مردی به نام لئوپولد بلوم."),
            StoryParagraph("He did not yet know what that meeting would mean, or how it would change him, or what the day would bring.", "هنوز نمی‌دانست آن ملاقات چه معنایی خواهد داشت، یا چگونه تغییرش می‌دهد، یا روز چه به ارمغان می‌آورد."),
            StoryParagraph("But he knew that something was beginning, something important, something that could not be stopped.", "اما می‌دانست چیزی آغاز شده، چیزی مهم، چیزی که نمی‌شد متوقفش کرد."),
            StoryParagraph("And so began the day of Ulysses, the day of Dublin, the day of the human soul.", "و اینگونه روز اولیس آغاز شد، روز دوبلین، روز روح انسانی.")
        )
    )

    // ─────────── فصل ۲: لئوپولد بلوم ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Leopold Bloom", titlePersian = "لئوپولد بلوم",
        paragraphs = listOf(
            StoryParagraph("In another part of Dublin, on the same morning, a man named Leopold Bloom was preparing breakfast for his wife.", "در بخش دیگری از دوبلین، همان صبح، مردی به نام لئوپولد بلوم داشت برای همسرش صبحانه آماده می‌کرد."),
            StoryParagraph("Bloom was thirty-eight years old, an advertising canvasser, a Jew in a Catholic city, a man who did not quite belong anywhere.", "بلوم سی و هشت ساله بود، تبلیغ‌کننده آگهی، یهودی در شهری کاتولیک، مردی که کاملاً به جایی تعلق نداشت."),
            StoryParagraph("His wife, Molly, was a singer, a beautiful woman with dark eyes and a sensual nature; she was having an affair with a man named Blazes Boylan.", "همسرش مالی، خواننده بود، زنی زیبا با چشمانی تیره و طبیعتی حسی؛ با مردی به نام بلیز بویلان رابطه داشت."),
            StoryParagraph("Bloom knew about the affair; he had known for some time; and he had done nothing about it, because he did not know what to do.", "بلوم از این رابطه خبر داشت؛ مدتی بود می‌دانست؛ و کاری نکرده بود، چون نمی‌دانست چه کند."),
            StoryParagraph("He had loved Molly once, deeply and truly; and perhaps he still loved her, in his own way, in the way that survives after passion has gone.", "روزی مالی را دوست داشته بود، عمیق و واقعی؛ و شاید هنوز دوستش داشت، به شیوه خودش، به شیوه‌ای که پس از رفتن شور باقی می‌ماند."),
            StoryParagraph("Bloom was a man of ordinary appearance and extraordinary inner life; he thought about everything, and he felt deeply, and he rarely spoke about what he thought or felt.", "بلوم مردی با ظاهر معمولی و زندگی درونی فوق‌العاده بود؛ درباره همه چیز فکر می‌کرد و عمیقاً حس می‌کرد و به‌ندرت درباره افکار یا احساساتش صحبت می‌کرد."),
            StoryParagraph("He made tea, and he made toast, and he brought the tray up to Molly in bed.", "چای درست کرد و نان تست و سینی را برای مالی در تختش بالا برد."),
            StoryParagraph("'What is it?' Molly asked, without opening her eyes.", "مالی بدون باز کردن چشمانش پرسید: «چیست؟»"),
            StoryParagraph("'Your breakfast,' Bloom said. 'And there is a letter for you.'", "بلوم گفت: «صبحانه‌ات. و نامه‌ای برایت هست.»"),
            StoryParagraph("Molly took the letter, and she saw the handwriting on the envelope, and she smiled, and she hid the smile.", "مالی نامه را گرفت و دست‌خط روی پاکت را دید و لبخند زد و لبخندش را پنهان کرد."),
            StoryParagraph("'Who is it from?' Bloom asked, though he knew.", "بلوم پرسید هرچند می‌دانست: «از کیست؟»"),
            StoryParagraph("'From Boylan,' Molly said. 'He is coming this afternoon.'", "مالی گفت: «از بویلان. امروز بعدازظهر می‌آید.»"),
            StoryParagraph("Bloom said nothing; he stood at the foot of the bed, and he looked at his wife, and he felt a pain that was so familiar it had become a part of him.", "بلوم چیزی نگفت؛ در پایین تخت ایستاد و به همسرش نگاه کرد و دردی حس کرد که آنقدر آشنا بود که بخشی از او شده بود."),
            StoryParagraph("'I will be out most of the day,' he said, at last. 'I have a funeral to attend.'", "سرانجام گفت: «بیشتر روز بیرون خواهم بود. باید در خاکسپاری شرکت کنم.»"),
            StoryParagraph("'Whose funeral?' Molly asked.", "مالی پرسید: «خاکسپاری کی؟»"),
            StoryParagraph("'Paddy Dignam,' Bloom said. 'He died suddenly. A stroke.'", "بلوم گفت: «پدی دیگنم. ناگهانی مرد. سکته.»"),
            StoryParagraph("'Poor man,' Molly said, and she did not sound as if she meant it.", "مالی گفت: «بیچاره.» و به نظر نمی‌رسید منظورش باشد."),
            StoryParagraph("Bloom left the room, and he went downstairs, and he sat in the kitchen, and he thought about his life.", "بلوم اتاق را ترک کرد و پایین رفت و در آشپزخانه نشست و به زندگی‌اش فکر کرد."),
            StoryParagraph("He thought about his father, Rudolph Bloom, who had killed himself when Bloom was a boy.", "به پدرش فکر کرد، رودولف بلوم، که خودش را کشته بود وقتی بلوم پسرکی بود."),
            StoryParagraph("He thought about his son, Rudy, who had died eleven days after birth, and whose death had broken something in Molly, and in Bloom too.", "به پسرش فکر کرد، رادی، که یازده روز پس از تولد مرده بود و مرگش چیزی در مالی شکسته بود و در بلوم هم."),
            StoryParagraph("He thought about his mother, Ellen, and about his wife, Molly, and about all the women he had loved and lost and failed.", "به مادرش الن فکر کرد و به همسرش مالی و به همه زنانی که دوست داشته و از دست داده و در آن‌ها شکست خورده بود."),
            StoryParagraph("He thought about his country, Ireland, which had never quite accepted him because he was a Jew, and about the land of his fathers, Hungary, which he had never seen.", "به کشورش فکر کرد، ایرلند، که هرگز کاملاً نپذیرفته بودش چون یهودی بود و به سرزمین پدرانش، مجارستان، که هرگز ندیده بود."),
            StoryParagraph("He thought about life, and about death, and about the strange, sad, beautiful business of being alive.", "به زندگی فکر کرد و به مرگ و به کار عجیب و اندوهناک و زیبای زنده بودن."),
            StoryParagraph("And then he got up, and he put on his hat, and he went out into the street.", "و بعد بلند شد و کلاهش را گذاشت و به خیابان رفت."),
            StoryParagraph("Dublin was busy that morning; the shops were open, the trams were running, the people were going about their business.", "دوبلین آن صبح شلوغ بود؛ مغازه‌ها باز، ترامواها در حرکت، مردم مشغول کارشان."),
            StoryParagraph("Bloom walked through the streets, and he watched the people, and he thought about each of them.", "بلوم در خیابان‌ها قدم زد و مردم را تماشا کرد و به هر یک از آنان فکر کرد."),
            StoryParagraph("He thought about the young woman in the bakery, and the old man on the bench, and the boy delivering newspapers.", "به زن جوان در نانوایی فکر کرد و به پیرمرد روی نیمکت و به پسری که روزنامه می‌رساند."),
            StoryParagraph("He thought about their lives, their hopes, their fears, their secrets; and he felt a great tenderness for all of them.", "به زندگی‌هایشان فکر کرد، به امیدهایشان، به ترس‌هایشان، به رازهایشان؛ و لطافتی عظیم برای همه‌شان حس کرد."),
            StoryParagraph("'We are all the same,' he thought. 'We all want the same things. We all suffer the same way. We all die alone.'", "فکر کرد: «همه‌مان یکی هستیم. همه‌مان همان چیزها را می‌خواهیم. همه‌مان به همان شیوه رنج می‌کشیم. همه‌مان تنها می‌میریم.»"),
            StoryParagraph("He thought about Stephen Dedalus, whom he had met a few times, and whom he admired for his intelligence and his honesty.", "به استیون ددالوس فکر کرد که چند بار دیده بودش و برای هوش و صداقتش تحسینش می‌کرد."),
            StoryParagraph("He thought about how he might help Stephen, how he might be a kind of father to him, how he might find in the young man a substitute for the son he had lost.", "فکر کرد چگونه ممکن است به استیون کمک کند، چگونه ممکن است نوعی پدر برایش باشد، چگونه ممکن است در جوانی جانشینی برای پسر از دست رفته‌اش بیابد."),
            StoryParagraph("He thought about the day ahead, and he felt a strange excitement, a sense that something was going to happen, something that would change everything.", "به روز پیش رو فکر کرد و هیجانی عجیب حس کرد، حسی که چیزی در شرف وقوع بود، چیزی که همه چیز را تغییر می‌داد."),
            StoryParagraph("And he walked on, through the streets of Dublin, on the morning of June 16, 1904.", "و به راه ادامه داد، در خیابان‌های دوبلین، در صبح ۱۶ ژوئن ۱۹۰۴."),
            StoryParagraph("He did not know what the day would bring; he did not know whom he would meet, or what he would learn, or how he would change.", "نمی‌دانست روز چه می‌آورد؛ نمی‌دانست با چه کسی ملاقات می‌کند، یا چه می‌آموزد، یا چگونه تغییر می‌کند."),
            StoryParagraph("But he knew that he was alive, and that this was enough; he knew that the ordinary day, the ordinary life, the ordinary man, contained within them all the wonder and mystery of existence.", "اما می‌دانست زنده است و همین کافی بود؛ می‌دانست روز معمولی، زندگی معمولی، مرد معمولی، تمام شگفتی و رمز وجود را در خود دارند."),
            StoryParagraph("And so began the journey of Leopold Bloom through his city, and through himself, and through the great stream of human consciousness.", "و اینگونه سفر لئوپولد بلوم آغاز شد از میان شهرش و از میان خودش و از میان جریان بزرگ آگاهی انسانی.")
        )
    )

