    private fun chapter3() = StoryChapter(
        number = 3, title = "Wandering the City", titlePersian = "گشت‌وگذار در شهر",
        paragraphs = listOf(
            StoryParagraph("Bloom wandered through Dublin all day, from morning until late at night, walking, riding, thinking, feeling, remembering.", "بلوم تمام روز در دوبلین سرگردان بود، از صبح تا شب دیرهنگام، راه می‌رفت، سوار می‌شد، فکر می‌کرد، حس می‌کرد، به یاد می‌آورد."),
            StoryParagraph("He went to the post office, and he went to the chemist, and he went to the Turkish baths, and he went to the funeral of Paddy Dignam.", "به پستخانه رفت و به داروخانه و به حمام‌های ترکی و به خاکسپاری پدی دیگنم."),
            StoryParagraph("At the funeral, he saw many men he knew: Simon Dedalus, the father of Stephen; Martin Cunningham, a friendly soul; John Power, a police officer; and others.", "در خاکسپاری مردان بسیاری را دید که می‌شناخت: سایمون ددالوس، پدر استیون؛ مارتین کانینگهام، روحی مهربان؛ جان پاور، افسر پلیس؛ و دیگران."),
            StoryParagraph("They talked about death, as men do at funerals, and about life, and about politics, and about the past.", "درباره مرگ صحبت کردند، همانطور که مردان در خاکسپاری‌ها می‌کنند و درباره زندگی و سیاست و گذشته."),
            StoryParagraph("Bloom thought about his own death, and about his father's death, and about his son's death; and he felt the weight of all of them.", "بلوم به مرگ خودش فکر کرد و به مرگ پدرش و به مرگ پسرش؛ و وزن همه‌شان را حس کرد."),
            StoryParagraph("He thought about the dead, and about how they lived on in memory, and about how memory was the only immortality we could know.", "به مردگان فکر کرد و به اینکه چگونه در حافظه زنده می‌مانند و به اینکه حافظه تنها جاودانگی‌ای بود که می‌توانستیم بشناسیم."),
            StoryParagraph("After the funeral, he went to the newspaper office, to arrange an advertisement for a client.", "بعد از خاکسپاری، به دفتر روزنامه رفت تا آگهی‌ای برای مشتری ترتیب دهد."),
            StoryParagraph("He walked through the busy streets, past shops and pubs and churches, past beggars and merchants and priests.", "در خیابان‌های شلوغ قدم زد، از کنار مغازه‌ها و میخانه‌ها و کلیساها، از کنار گداها و تاجران و کشیشان."),
            StoryParagraph("He saw a young woman across the street, and he watched her, and he thought about desire, and about beauty, and about the fleeting nature of all things.", "زنی جوان را آنسوی خیابان دید و تماشایش کرد و به میل فکر کرد و به زیبایی و به طبیعت گذرای همه چیز."),
            StoryParagraph("He went to the National Library, and he thought about books and learning, and about how much he did not know.", "به کتابخانه ملی رفت و به کتاب‌ها و دانش فکر کرد و به اینکه چقدر نمی‌داند."),
            StoryParagraph("He went to a pub, and he drank a glass of burgundy, and he ate a gorgonzola sandwich, and he listened to the talk around him.", "به میخانه‌ای رفت و یک لیوان بورگوندی نوشید و ساندویچ گورگونزولا خورد و به صحبت‌های اطرافش گوش داد."),
            StoryParagraph("The talk was about politics, about the Irish question, about Home Rule, about the English, about the Jews, about everything and nothing.", "صحبت درباره سیاست بود، درباره مسئله ایرلند، درباره خودمختاری، درباره انگلیسی‌ها، درباره یهودی‌ها، درباره همه چیز و هیچ."),
            StoryParagraph("Bloom, who was a Jew, listened in silence, and he felt the sting of the casual anti-Semitism that surrounded him everywhere.", "بلوم که یهودی بود در سکوت گوش داد و نیش یهودستیزی معمولی را حس کرد که همه‌جا احاطه‌اش کرده بود."),
            StoryParagraph("'They do not even know they are hurting me,' he thought. 'They do not even know I am here.'", "فکر کرد: «آن‌ها حتی نمی‌دانند که دارند آزارم می‌دهند. حتی نمی‌دانند اینجام.»"),
            StoryParagraph("But he did not complain; he did not argue; he simply observed, and he simply endured, and he simply loved.", "اما شکایت نکرد؛ بحث نکرد؛ تنها مشاهده کرد و تنها تحمل کرد و تنها عشق ورزید."),
            StoryParagraph("He thought about Molly, and about Boylan, and about what was happening in his house that afternoon.", "به مالی فکر کرد و به بویلان و به آنچه آن بعدازظهر در خانه‌اش می‌گذشت."),
            StoryParagraph("He thought about the jealousy that burned in him, and about the way he had learned to live with it, and about the strange, sad acceptance that had come with time.", "به حسادتی فکر کرد که در او می‌سوخت و به شیوه‌ای که یاد گرفته بود با آن زندگی کند و به پذیرش عجیب و اندوهناکی که با زمان آمده بود."),
            StoryParagraph("'It is not her fault,' he thought. 'It is not my fault. It is just what happens. It is life.'", "فکر کرد: «تقصیر او نیست. تقصیر من نیست. تنها این است که اتفاق می‌افتد. این زندگی است.»"),
            StoryParagraph("He thought about his father, and about how he had never really known him, and about how much he wished he had.", "به پدرش فکر کرد و به اینکه هرگز واقعاً نشناخته بودش و به اینکه چقدر آرزو می‌کرد شناخته بود."),
            StoryParagraph("He thought about his son, Rudy, and about the small life that had ended before it had begun.", "به پسرش رادی فکر کرد و به زندگی کوچکی که پیش از آغاز شدن پایان یافته بود."),
            StoryParagraph("He thought about Stephen Dedalus, and about the young man's intelligence, his pride, his loneliness.", "به استیون ددالوس فکر کرد و به هوش جوان، به غرورش، به تنهایی‌اش."),
            StoryParagraph("He thought about the possibility that Stephen might be, in some sense, his spiritual son, the son he had lost and might find again.", "به این احتمال فکر کرد که استیون ممکن است به نوعی پسر روحی‌اش باشد، پسری که از دست داده بود و شاید دوباره می‌یافت."),
            StoryParagraph("As evening came, he went to the beach at Sandymount, and he sat on the rocks, and he watched the young women, and he watched the sunset.", "هنگام غروب، به ساحل سندی‌مونت رفت و روی صخره‌ها نشست و زنان جوان را تماشا کرد و غروب را تماشا کرد."),
            StoryParagraph("A young woman named Gerty MacDowell was sitting nearby, and Bloom watched her, and he thought about desire, and about beauty, and about how the two were always entwined with sorrow.", "زنی جوان به نام گرتی مک‌داول نزدیک نشسته بود و بلوم تماشایش کرد و به میل فکر کرد و به زیبایی و به اینکه این دو همیشه با اندوه درهم‌بافته‌اند."),
            StoryParagraph("The fireworks began, and the sky was filled with color and light, and Bloom felt a moment of happiness, a moment of peace.", "آتش‌بازی شروع شد و آسمان پر از رنگ و نور شد و بلوم لحظه‌ای از شادی حس کرد، لحظه‌ای از آرامش."),
            StoryParagraph("But the moment passed, as all moments pass, and he was left with himself, and with his thoughts, and with the darkness that was coming.", "اما لحظه گذشت، همانطور که همه لحظه‌ها می‌گذرند و با خودش ماند و با افکارش و با تاریکی که می‌آمد."),
            StoryParagraph("He went to the hospital to visit a woman who was in labor, a friend of a friend, and there he met Stephen Dedalus.", "به بیمارستان رفت تا زنی را ملاقات کند که در زایمان بود، دوست دوستی و آنجا با استیون ددالوس آشنا شد."),
            StoryParagraph("Stephen was drinking with a group of medical students, and he was already drunk, and he was talking wildly about art and life and death.", "استیون با گروهی از دانشجویان پزشکی مشروب می‌خورد و از قبل مست بود و وحشیانه درباره هنر و زندگی و مرگ صحبت می‌کرد."),
            StoryParagraph("Bloom joined them, and he watched Stephen, and he felt a strange kinship with the young man, a sense that they were connected in some way he could not name.", "بلوم به آن‌ها پیوست و استیون را تماشا کرد و خویشاوندی عجیبی با آن جوان حس کرد، حسی که به نحوی که نمی‌توانست نامش را ببرد به هم وصل بودند."),
            StoryParagraph("Later that night, they went together to a brothel, and Stephen had strange visions, and he saw his mother's ghost, and he broke a chandelier in a rage.", "بعدتر آن شب با هم به فاحشه‌خانه‌ای رفتند و استیون رؤیاهای عجیبی دید و روح مادرش را دید و در خشم چلچراغی را شکست."),
            StoryParagraph("Bloom saved him from the police, and then he took him to a cabman's shelter for coffee, and they talked.", "بلوم او را از پلیس نجات داد و بعد او را برای قهوه به پناهگاه کالسکه‌رانان برد و صحبت کردند."),
            StoryParagraph("They talked about Ireland, and about Jews, and about Shakespeare, and about the meaning of everything.", "درباره ایرلند صحبت کردند و درباره یهودی‌ها و درباره شکسپیر و درباره معنای همه چیز."),
            StoryParagraph("'You are a Jew,' Stephen said. 'And I am an Irishman. And we are both exiles in our own country.'", "استیون گفت: «تو یهودی هستی. و من ایرلندی. و هر دو در کشور خودمان تبعیدیم.»"),
            StoryParagraph("'Yes,' Bloom said. 'But perhaps that is not a curse. Perhaps it is a gift.'", "بلوم گفت: «بله. اما شاید این نفرین نیست. شاید هدیه است.»"),
            StoryParagraph("'How so?' Stephen asked.", "استیون پرسید: «چگونه؟»"),
            StoryParagraph("'Because it means we can see what others cannot see,' Bloom said. 'It means we are not blinded by the assumptions of our time. It means we are free.'", "بلوم گفت: «چون بدان معناست ما می‌توانیم چیزی را ببینیم که دیگران نمی‌بینند. بدان معناست که با فرض‌های زمانه‌مان کور نشده‌ایم. بدان معناست که آزادیم.»"),
            StoryParagraph("Stephen thought about this, and he did not know whether Bloom was right, or whether he was simply trying to comfort him.", "استیون به این فکر کرد و نمی‌دانست بلوم درست می‌گوید، یا تنها تلاش می‌کند دلداری‌اش دهد."),
            StoryParagraph("But he felt, in that moment, a kind of warmth toward the older man, a kind of gratitude, a kind of love.", "اما در آن لحظه نوعی گرمی نسبت به آن مرد مسن‌تر حس کرد، نوعی سپاس، نوعی عشق."),
            StoryParagraph("And so the day ended, and the night began, and the two men, the young and the old, walked together through the dark streets of Dublin.", "و اینگونه روز تمام شد و شب آغاز شد و آن دو مرد، جوان و پیر، با هم در خیابان‌های تاریک دوبلین قدم زدند."),
            StoryParagraph("And somewhere in the city, Molly Bloom lay in her bed, thinking her own thoughts, remembering her own memories, dreaming her own dreams.", "و جایی در شهر، مالی بلوم در تختش دراز کشیده بود، به افکار خودش فکر می‌کرد، خاطرات خودش را به یاد می‌آورد، رؤیاهای خودش را می‌دید.")
        )
    )

    // ─────────── فصل ۴: جریان آگاهی ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "The Stream of Consciousness", titlePersian = "جریان آگاهی",
        paragraphs = listOf(
            StoryParagraph("Ulysses is written in a style called stream of consciousness, in which the thoughts and feelings of the characters flow freely, without order, without explanation.", "اولیس به سبکی نوشته شده که جریان آگاهی نامیده می‌شود، که در آن افکار و احساسات شخصیت‌ها آزادانه جاری می‌شوند، بدون نظم، بدون توضیح."),
            StoryParagraph("The novel does not tell us what the characters are thinking; it shows us their thoughts as they happen, in all their confusion and beauty.", "رمان به ما نمی‌گوید شخصیت‌ها چه فکر می‌کنند؛ افکارشان را همانطور که رخ می‌دهند نشانمان می‌دهد، در تمام آشفتگی و زیبایی‌شان."),
            StoryParagraph("We are inside the minds of the characters, and we see the world through their eyes, and we feel the world through their hearts.", "داخل ذهن شخصیت‌ها هستیم و جهان را از چشمانشان می‌بینیم و جهان را از قلب‌هایشان حس می‌کنیم."),
            StoryParagraph("Bloom thinks about his wife, about his son, about his father, about his city, about his God, about his death.", "بلوم به همسرش فکر می‌کند، به پسرش، به پدرش، به شهرش، به خدایش، به مرگش."),
            StoryParagraph("He thinks about the smell of soap, and the taste of wine, and the touch of a woman's hand, and the memory of a kiss.", "به بوی صابون فکر می‌کند و طعم شراب و لمس دست زنی و خاطره بوسه‌ای."),
            StoryParagraph("He thinks about the past and the future, about what has been and what might be, about everything that has ever happened to him.", "به گذشته و آینده فکر می‌کند، به آنچه بوده و آنچه می‌تواند باشد، به هر چیزی که هرگز برایش اتفاق افتاده."),
            StoryParagraph("Stephen thinks about his mother, about her death, about his refusal to pray, about the guilt that haunts him.", "استیون به مادرش فکر می‌کند، به مرگش، به امتناعش از دعا، به گناهی که تسخیرش می‌کند."),
            StoryParagraph("He thinks about his art, about his writing, about his ambition to create something beautiful out of the chaos of his life.", "به هنرش فکر می‌کند، به نوشتنش، به جاه‌طلبی‌اش که چیزی زیبا از آشوب زندگی‌اش بیافریند."),
            StoryParagraph("He thinks about Ireland, about her history, about her suffering, about her future.", "به ایرلند فکر می‌کند، به تاریخش، به رنجش، به آینده‌اش."),
            StoryParagraph("He thinks about language, about words, about the way that words both reveal and conceal the truth.", "به زبان فکر می‌کند، به کلمات، به شیوه‌ای که کلمات هم حقیقت را آشکار می‌کنند و هم پنهان."),
            StoryParagraph("And Molly, in her bed, thinks about her lovers, her husband, her daughter, her childhood in Gibraltar, her dreams of a life she never had.", "و مالی، در تختش، به عاشقانش فکر می‌کند، به شوهرش، به دخترش، به کودکی‌اش در جبل‌طارق، به رؤیاهای زندگی‌ای که هرگز نداشت."),
            StoryParagraph("She thinks about the flowers, and the sea, and the sun, and the men who have loved her.", "به گل‌ها فکر می‌کند و به دریا و به خورشید و به مردانی که دوستش داشته‌اند."),
            StoryParagraph("She thinks about her body, and its pleasures, and its pains, and its mortality.", "به بدنش فکر می‌کند، به لذت‌هایش، به دردهایش، به فناپذیری‌اش."),
            StoryParagraph("She thinks about her husband, whom she has betrayed, and whom she still loves, in her own way, in a way she cannot explain.", "به شوهرش فکر می‌کند که به او خیانت کرده و هنوز دوستش دارد، به شیوه خودش، به شیوه‌ای که نمی‌تواند توضیح دهد."),
            StoryParagraph("The novel moves through these three minds, and through many others, in a great symphony of human consciousness.", "رمان از میان این سه ذهن حرکت می‌کند و از میان بسیاری ذهن دیگر، در سمفونی بزرگ آگاهی انسانی."),
            StoryParagraph("It is not a story with a plot, in the usual sense; it is a story of being alive, of being human, of being caught in the great stream of time.", "داستانی با طرح نیست، به معنای معمول؛ داستانی است از زنده بودن، از انسان بودن، از گرفتار بودن در جریان بزرگ زمان."),
            StoryParagraph("It is a celebration of the ordinary, the small, the unnoticed; of a man buying soap, of a woman putting on her shoes, of a child running down the street.", "جشنی است برای معمولی، برای کوچک، برای نادیده؛ برای مردی که صابون می‌خرد، برای زنی که کفش‌هایش را می‌پوشد، برای کودکی که در خیابان می‌دود."),
            StoryParagraph("It is a celebration of language, of the English language, of all the words that have ever been spoken, and all the words that are yet to be spoken.", "جشنی است برای زبان، برای زبان انگلیسی، برای تمام کلماتی که هرگز گفته شده‌اند و تمام کلماتی که هنوز گفته می‌شوند."),
            StoryParagraph("Joyce uses every style, every form, every trick of language, to capture the way that consciousness actually works.", "جویس از هر سبکی استفاده می‌کند، هر فرمی، هر ترفندی از زبان، تا شیوه‌ای را که آگاهی واقعاً کار می‌کند ثبت کند."),
            StoryParagraph("He uses puns, and allusions, and parodies, and every literary form that has ever existed, from the epic to the limerick, from the sermon to the song.", "از جناس استفاده می‌کند و تلمیح و پارودی و هر فرم ادبی که هرگز وجود داشته، از حماسه تا شعر طنز، از موعظه تا آواز."),
            StoryParagraph("He writes in the styles of other writers, mocking them, honoring them, showing us that all writing is borrowed, that all language is inherited.", "به سبک نویسندگان دیگر می‌نویسد، مسخره‌شان می‌کند، احترامشان می‌گذارد، نشانمان می‌دهد که تمام نوشتن قرضی است، که تمام زبان موروثی است."),
            StoryParagraph("And yet, out of all this complexity, out of all this difficulty, emerges something simple and beautiful: a portrait of human beings living, loving, suffering, and enduring.", "و با این حال، از تمام این پیچیدگی، از تمام این دشواری، چیزی ساده و زیبا بیرون می‌آید: پرتره‌ای از انسان‌هایی که زندگی می‌کنند، عشق می‌ورزند، رنج می‌کشند و تحمل می‌کنند."),
            StoryParagraph("Bloom is not a hero, in the traditional sense; he is not brave, not brilliant, not beautiful.", "بلوم قهرمان نیست، به معنای سنتی؛ شجاع نیست، درخشان نیست، زیبا نیست."),
            StoryParagraph("He is a man of ordinary abilities and extraordinary compassion; a man who has suffered much and who has learned to be kind; a man who has lost much and who has learned to keep going.", "مردی است با توانایی‌های معمولی و شفقتی فوق‌العاده؛ مردی که بسیار رنج کشیده و آموخته مهربان باشد؛ مردی که بسیار از دست داده و آموخته ادامه دهد."),
            StoryParagraph("Stephen is not a hero either; he is proud, and confused, and often cruel to those who love him.", "استیون هم قهرمان نیست؛ مغرور است و گیج و اغلب بی‌رحم به کسانی که دوستش دارند."),
            StoryParagraph("But he is also honest, and brilliant, and searching for something that will give his life meaning.", "اما صادق هم هست و درخشان و در جستجوی چیزی که به زندگی‌اش معنا می‌دهد."),
            StoryParagraph("Molly is not a heroine, in the Victorian sense; she is unfaithful, and sensuous, and not always kind.", "مالی قهرمان زن نیست، به معنای ویکتوریایی؛ بی‌وفا است و حسی و همیشه مهربان نیست."),
            StoryParagraph("But she is also warm, and alive, and deeply, profoundly human.", "اما گرم هم هست و زنده و عمیقاً، به‌شکل عمیقی، انسانی."),
            StoryParagraph("These three characters, in their imperfection, in their weakness, in their suffering, are more real, more true, more human than any heroes could ever be.", "این سه شخصیت، در نقصشان، در ضعفشان، در رنجشان، واقعی‌تر، راستین‌تر، انسانی‌ترند از هر قهرمانی که هرگز می‌توانست باشد."),
            StoryParagraph("And that, perhaps, is the point of the novel: not to show us heroes, but to show us ourselves.", "و این، شاید، همان هدف رمان است: نه نشان دادن قهرمانان، بلکه نشان دادن خودمان."),
            StoryParagraph("To show us that the ordinary life, the ordinary day, the ordinary person, contains within them all the beauty and tragedy and wonder of existence.", "نشان دادن اینکه زندگی معمولی، روز معمولی، شخص معمولی، تمام زیبایی و تراژدی و شگفتی وجود را در خود دارند."),
            StoryParagraph("To show us that we do not need to be heroes to be human; we only need to be alive, and to love, and to endure.", "نشان دادن اینکه نیازی نیست قهرمان باشیم تا انسان باشیم؛ تنها باید زنده باشیم و عشق بورزیم و تحمل کنیم."),
            StoryParagraph("This is what Joyce believed, and this is what he wrote; and out of this belief, out of this writing, came a novel that has changed literature forever.", "این همان چیزی است که جویس باور داشت و این همان چیزی است که نوشت؛ و از این باور، از این نوشتن، رمانی آمد که ادبیات را برای همیشه تغییر داد."),
            StoryParagraph("Ulysses is not an easy book; it is not a book for a lazy afternoon; it is a book that demands everything from its reader.", "اولیس کتاب آسانی نیست؛ کتاب یک بعدازظهر تنبل نیست؛ کتابی است که همه چیز را از خواننده‌اش می‌طلبد."),
            StoryParagraph("But for those who give it everything, it gives back everything, and more.", "اما برای کسانی که همه چیز به آن می‌دهند، همه چیز و بیشتر پس می‌دهد."),
            StoryParagraph("It gives back a vision of life that is both ordinary and transcendent, both particular and universal, both Dublin and everywhere.", "بینشی از زندگی پس می‌دهد که هم معمولی و هم متعالی است، هم خاص و هم جهانی، هم دوبلین و هم همه‌جا."),
            StoryParagraph("It gives back a vision of the human soul that is both honest about its darkness and hopeful about its light.", "بینشی از روح انسانی پس می‌دهد که هم درباره تاریکی‌اش صادق است و هم درباره نورش امیدوار."),
            StoryParagraph("And it gives back, above all, a vision of love — not romantic love, not idealized love, but the deep, patient, enduring love that binds human beings together through all the trials of existence.", "و بیش از همه، بینشی از عشق پس می‌دهد — نه عشق رمانتیک، نه عشق آرمانی، بلکه عشق عمیق و صبور و پایدار که انسان‌ها را در تمام آزمون‌های وجود به هم می‌بندد."),
            StoryParagraph("This is the message of Ulysses, and it is a message that will never grow old.", "این پیام اولیس است و پیامی است که هرگز کهنه نمی‌شود.")
        )
    )

    // ─────────── فصل ۵: تک‌گویی مالی ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "Molly's Soliloquy", titlePersian = "تک‌گویی مالی",
        paragraphs = listOf(
            StoryParagraph("Late at night, after Bloom had returned home, after the two men had said goodbye, Molly Bloom lay awake in her bed, thinking.", "شب دیرهنگام، پس از اینکه بلوم به خانه برگشته بود، پس از اینکه آن دو مرد خداحافظی کرده بودند، مالی بلوم بیدار در تختش دراز کشیده بود و فکر می‌کرد."),
            StoryParagraph("Her thoughts came in a great rush, without punctuation, without pause, without order; the whole stream of her consciousness pouring out.", "افکارش در هجومی بزرگ آمدند، بدون نقطه‌گذاری، بدون توقف، بدون نظم؛ تمام جریان آگاهی‌اش بیرون می‌ریخت."),
            StoryParagraph("She thought about her day, about Boylan, about the pleasure he had given her, about the shame she felt afterward.", "به روزش فکر کرد، به بویلان، به لذتی که به او داده بود، به شرمی که پس از آن حس کرده بود."),
            StoryParagraph("She thought about Bloom, whom she had betrayed, whom she had loved, whom she had disappointed, whom she could not leave.", "به بلوم فکر کرد که به او خیانت کرده بود، که دوستش داشته، که ناامیدش کرده، که نمی‌توانست ترکش کند."),
            StoryParagraph("She thought about the strange, quiet, patient man who had married her, and who had stayed with her through everything, and who had never stopped loving her.", "به مرد عجیب و ساکت و صبوری فکر کرد که با او ازدواج کرده بود و در تمام چیزها با او مانده بود و هرگز از دوست داشتنش دست نکشیده بود."),
            StoryParagraph("She thought about her childhood in Gibraltar, where she had grown up under the sun, where she had known a different kind of life.", "به کودکی‌اش در جبل‌طارق فکر کرد، جایی که زیر آفتاب بزرگ شده بود، جایی که زندگی متفاوتی شناخته بود."),
            StoryParagraph("She thought about her first love, Mulvey, and about how he had kissed her, and about how she had felt.", "به عشق اولش مولوای فکر کرد و به اینکه چگونه بوسیده بودش و به اینکه چگونه حس کرده بود."),
            StoryParagraph("She thought about her daughter, Milly, who had grown up and gone away, who was now becoming a woman.", "به دخترش میلی فکر کرد که بزرگ شده و رفته بود، که حالا زن می‌شد."),
            StoryParagraph("She thought about her son, Rudy, who had died, and about how she had never quite recovered from that loss.", "به پسرش رادی فکر کرد که مرده بود و به اینکه هرگز کاملاً از آن فقدان بهبود نیافته بود."),
            StoryParagraph("She thought about her body, about its changes, about its aging, about its eventual death.", "به بدنش فکر کرد، به تغییراتش، به پیری‌اش، به مرگ نهایی‌اش."),
            StoryParagraph("She thought about the men she had known, and about what they had given her, and about what they had taken from her.", "به مردانی فکر کرد که شناخته بود و به آنچه به او داده بودند و به آنچه از او گرفته بودند."),
            StoryParagraph("She thought about love, and about whether she had ever truly loved anyone, and about whether she had ever been truly loved.", "به عشق فکر کرد و به اینکه آیا هرگز واقعاً کسی را دوست داشته و آیا هرگز واقعاً دوست داشته شده."),
            StoryParagraph("She thought about God, about the church, about the faith she had abandoned, about the prayers she still sometimes murmured in the dark.", "به خدا فکر کرد، به کلیسا، به ایمانی که رها کرده بود، به دعاهایی که هنوز گاهی در تاریکی زمزمه می‌کرد."),
            StoryParagraph("She thought about the flowers, and about how much she loved them, and about how Bloom had brought her flowers once, long ago.", "به گل‌ها فکر کرد و به اینکه چقدر دوستشان داشت و به اینکه بلوم روزی، مدت‌ها پیش، برایش گل آورده بود."),
            StoryParagraph("She thought about the sea, and about how she loved to swim in it, and about the feeling of the water on her skin.", "به دریا فکر کرد و به اینکه چقدر دوست داشت در آن شنا کند و به حس آب بر پوستش."),
            StoryParagraph("She thought about the sun, and about the warmth of it, and about the way it made her feel alive.", "به خورشید فکر کرد و به گرمایش و به شیوه‌ای که زنده حسش می‌کرد."),
            StoryParagraph("She thought about the earth, and about the things that grew from it, and about the cycle of life and death and rebirth.", "به زمین فکر کرد و به چیزهایی که از آن می‌روید و به چرخه زندگی و مرگ و تولد دوباره."),
            StoryParagraph("And then her thoughts turned to Bloom again, to the small kindnesses he had shown her, to the patience he had shown her, to the love he had never ceased to give.", "و بعد افکارش دوباره به بلوم چرخید، به مهربانی‌های کوچکی که به او نشان داده بود، به صبری که نشان داده بود، به عشقی که هرگز از بخشیدنش دست نکشیده بود."),
            StoryParagraph("She thought about how she had hurt him, and about how he had forgiven her, and about how he had never once reproached her.", "به اینکه چطور زخمی‌اش کرده بود فکر کرد و به اینکه چطور بخشیده بودش و به اینکه حتی یک بار هم سرزنشش نکرده بود."),
            StoryParagraph("She thought about how she had taken him for granted, and about how she had never fully appreciated him, and about how she wished she had.", "به اینکه چطور او را مسلم گرفته بود فکر کرد و به اینکه هرگز کاملاً ارزشش را ندانسته بود و به اینکه آرزو می‌کرد دانسته بود."),
            StoryParagraph("She thought about how she had once loved him, in the beginning, when they were young, when everything was new.", "به اینکه روزی دوستش داشته بود فکر کرد، در آغاز، وقتی جوان بودند، وقتی همه چیز نو بود."),
            StoryParagraph("And she thought about how she might love him again, if she let herself, if she allowed herself to see him as he was.", "و به اینکه شاید دوباره دوستش بدارد فکر کرد، اگر به خودش اجازه می‌داد، اگر به خودش اجازه می‌داد او را همانطور که هست ببیند."),
            StoryParagraph("She thought about the years they had spent together, and about the years they still might spend, and about the strange, quiet, enduring love that connected them.", "به سال‌هایی که با هم گذرانده بودند فکر کرد و به سال‌هایی که هنوز می‌توانستند بگذرانند و به عشق عجیب و ساکت و پایدار که وصلشان می‌کرد."),
            StoryParagraph("She thought about the small things: the way he made tea in the morning, the way he hummed to himself, the way he kissed her forehead before leaving.", "به چیزهای کوچک فکر کرد: شیوه‌ای که صبح‌ها چای درست می‌کرد، شیوه‌ای که زیر لب زمزمه می‌کرد، شیوه‌ای که پیش از رفتن پیشانی‌اش را می‌بوسید."),
            StoryParagraph("She thought about how she would say yes to him, if he asked her again, if he asked her to marry him all over again.", "به اینکه چگونه به او بله می‌گفت فکر کرد، اگر دوباره ازش می‌پرسید، اگر دوباره از او می‌خواست با او ازدواج کند."),
            StoryParagraph("And then, at last, her thoughts settled, and her mind grew quiet, and she began to drift toward sleep.", "و بعد، سرانجام، افکارش آرام شدند و ذهنش ساکت شد و شروع کرد به لغزیدن به سمت خواب."),
            StoryParagraph("But before she slept, she spoke, in her own voice, in her own words, the words that would end the novel.", "اما پیش از خوابیدن، سخن گفت، با صدای خودش، با کلمات خودش، کلماتی که رمان را پایان می‌دادند."),
            StoryParagraph("'Yes,' she said, 'I said yes, I will yes.'", "گفت: «بله، گفتم بله، بله خواهم گفت.»"),
            StoryParagraph("'Yes,' she said, 'I said yes.'", "گفت: «بله، گفتم بله.»"),
            StoryParagraph("'Yes,' she said, 'I will.'", "گفت: «بله، خواهم گفت.»"),
            StoryParagraph("The word echoed through the room, through the house, through the city, through the world.", "کلمه در اتاق پژواک کرد، در خانه، در شهر، در جهان."),
            StoryParagraph("'Yes' — the word of affirmation, the word of life, the word of love.", "«بله» — کلمه تأیید، کلمه زندگی، کلمه عشق."),
            StoryParagraph("In the midst of all the suffering, all the confusion, all the darkness, Molly Bloom had said yes to life.", "در میان تمام رنج، تمام گیجی، تمام تاریکی، مالی بلوم به زندگی بله گفته بود."),
            StoryParagraph("She had said yes to love, yes to her husband, yes to the world, yes to everything.", "به عشق بله گفته بود، به شوهرش بله، به جهان بله، به همه چیز بله."),
            StoryParagraph("And that yes, that simple, powerful, life-affirming yes, was the last word of the novel, and perhaps the greatest word in all of literature.", "و آن بله، آن بله ساده و قوی و زندگی‌ستا، آخرین کلمه رمان بود و شاید بزرگ‌ترین کلمه در تمام ادبیات."),
            StoryParagraph("For in the end, Joyce suggests, we are not saved by our ideas, or our philosophies, or our achievements.", "زیرا در پایان، جویس پیشنهاد می‌دهد، ما نه با ایده‌هایمان نجات می‌یابیم، نه با فلسفه‌هایمان، نه با دستاوردهایمان."),
            StoryParagraph("We are saved by our willingness to say yes to life, with all its suffering, with all its joy, with all its mystery.", "ما با آمادگی‌مان برای بله گفتن به زندگی نجات می‌یابیم، با تمام رنجش، با تمام شادیش، با تمام رمز و رازش."),
            StoryParagraph("We are saved by love, by patience, by endurance, by the simple, daily, unglamorous courage of continuing to live.", "ما با عشق نجات می‌یابیم، با صبر، با تحمل، با شجاعت ساده و روزانه و بی‌جذابیت ادامه دادن به زندگی."),
            StoryParagraph("And so the novel ends, with Molly's yes, with the sunrise coming, with a new day beginning, with hope.", "و اینگونه رمان پایان می‌یابد، با بله مالی، با طلوع در راه، با روزی نو در آغاز، با امید."),
            StoryParagraph("And that hope, that yes, that love, is what makes Ulysses more than a difficult novel, more than a literary experiment, more than a masterpiece.", "و آن امید، آن بله، آن عشق، همان چیزی است که اولیس را بیش از رمانی دشوار می‌کند، بیش از آزمایشی ادبی، بیش از شاهکاری."),
            StoryParagraph("It makes it a testament to the human spirit, a celebration of the human heart, a gift to the human race.", "آن را شهادتی برای روح انسانی می‌کند، جشنی برای قلب انسانی، هدیه‌ای برای نژاد انسانی."),
            StoryParagraph("And that is why we read it, and reread it, and return to it again and again, because in its great darkness we find a greater light.", "و به همین دلیل است که می‌خوانیمش و بازمی‌خوانیمش و دوباره و دوباره بازمی‌گردیم به آن، زیرا در تاریکی بزرگش نوری بزرگ‌تر می‌یابیم."),
            StoryParagraph("Yes, Joyce says. Yes to life. Yes to love. Yes to everything.", "بله، جویس می‌گوید. بله به زندگی. بله به عشق. بله به همه چیز.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("Ulysses, published in 1922, is one of the most important novels ever written, and one of the most difficult.", "اولیس، منتشرشده در ۱۹۲۲، یکی از مهم‌ترین رمان‌های نوشته‌شده و یکی از دشوارترین است."),
            StoryParagraph("It tells the story of a single day in Dublin, June 16, 1904, and of three characters — Stephen Dedalus, Leopold Bloom, and Molly Bloom — whose lives intersect and intertwine.", "داستان یک روز در دوبلین را تعریف می‌کند، ۱۶ ژوئن ۱۹۰۴ و سه شخصیت — استیون ددالوس، لئوپولد بلوم و مالی بلوم — که زندگی‌هایشان تلاقی و درهم‌بافتگی دارند."),
            StoryParagraph("The title refers to Homer's Odyssey, and the novel is structured as a modern parallel to that ancient epic.", "عنوان به اودیسه هومر اشاره دارد و رمان به‌عنوان موازی مدرن با آن حماسه کهن ساختار یافته."),
            StoryParagraph("Stephen is Telemachus, the son in search of his father; Bloom is Odysseus, the wanderer in search of home; Molly is Penelope, the wife who waits.", "استیون تلماخوس است، پسری در جستجوی پدرش؛ بلوم اودیسیوس است، سرگردانی در جستجوی خانه؛ مالی پنه‌لوپه است، همسری که منتظر می‌ماند."),
            StoryParagraph("But Joyce's novel is not a simple retelling; it is a transformation, a reinvention, a radical reimagining of what an epic could be.", "اما رمان جویس بازگویی ساده‌ای نیست؛ دگرگونی است، از نو آفریدن، بازتصوری رادیکال از آنچه حماسه می‌تواند باشد."),
            StoryParagraph("Instead of heroes and gods, Joyce gives us ordinary people; instead of great battles and voyages, he gives us the small events of an ordinary day.", "به جای قهرمانان و خدایان، جویس آدم‌های معمولی به ما می‌دهد؛ به جای نبردهای بزرگ و سفرها، رویدادهای کوچک یک روز معمولی."),
            StoryParagraph("Instead of a single, unified narrative, he gives us a hundred different styles, a thousand different voices, an infinity of ways of telling a story.", "به جای روایتی واحد و یکپارچه، صد سبک مختلف به ما می‌دهد، هزار صدای مختلف، بی‌نهایتی از شیوه‌های داستان گفتن."),
            StoryParagraph("And yet, out of all this complexity, out of all this experimentation, emerges something simple and profound: a vision of what it means to be alive.", "و با این حال، از تمام این پیچیدگی، از تمام این آزمایش، چیزی ساده و عمیق بیرون می‌آید: بینشی از معنای زنده بودن."),
            StoryParagraph("The novel shows us that the ordinary life is not ordinary at all; that the everyday contains the eternal; that the small contains the infinite.", "رمان نشانمان می‌دهد زندگی معمولی اصلاً معمولی نیست؛ روزمره ابدی را در خود دارد؛ کوچک بی‌نهایت را در خود دارد."),
            StoryParagraph("It shows us that a man buying a bar of soap is as worthy of attention as a hero conquering a city.", "نشانمان می‌دهد مردی که قالب صابونی می‌خرد به همان اندازه شایسته توجه است که قهرمانی که شهری را فتح می‌کند."),
            StoryParagraph("It shows us that a woman lying in bed, thinking her thoughts, is as fascinating as any goddess or queen.", "نشانمان می‌دهد زنی که در تخت دراز کشیده و به افکارش فکر می‌کند به اندازه هر الهه یا ملکه‌ای جذاب است."),
            StoryParagraph("And it shows us that the human mind, in all its confusion, in all its darkness, in all its strange beauty, is the greatest subject that art can ever address.", "و نشانمان می‌دهد ذهن انسانی، در تمام گیجی‌اش، در تمام تاریکی‌اش، در تمام زیبایی عجیبش، بزرگ‌ترین موضوعی است که هنر می‌تواند به آن بپردازد."),
            StoryParagraph("Joyce spent seven years writing the novel, and he changed literature forever.", "جویس هفت سال صرف نوشتن رمان کرد و ادبیات را برای همیشه تغییر داد."),
            StoryParagraph("Before Ulysses, the novel was a form of storytelling; after Ulysses, it became a form of consciousness.", "پیش از اولیس، رمان فرمی از داستان‌گویی بود؛ پس از اولیس، فرمی از آگاهی شد."),
            StoryParagraph("Before Joyce, writers wrote about what happened; after Joyce, writers wrote about what was thought, what was felt, what was experienced.", "پیش از جویس، نویسندگان درباره آنچه اتفاق می‌افتاد می‌نوشتند؛ پس از جویس، نویسندگان درباره آنچه فکر می‌شد، آنچه حس می‌شد، آنچه تجربه می‌شد نوشتند."),
            StoryParagraph("The novel was banned in many countries when it was first published; it was considered obscene, scandalous, dangerous.", "رمان وقتی نخستین بار منتشر شد در بسیاری کشورها ممنوع شد؛ فحشا محسوب می‌شد، رسوایی، خطرناک."),
            StoryParagraph("But time has proven Joyce right; time has shown that the novel was not obscene but honest, not scandalous but true, not dangerous but essential.", "اما زمان جویس را محق ثابت کرده؛ زمان نشان داده رمان فحشا نبود بلکه صادق بود، نه رسوایی بلکه راستین، نه خطرناک بلکه ضروری."),
            StoryParagraph("Today, Ulysses is recognized as one of the greatest works of literature ever written, and June 16 is celebrated around the world as Bloomsday.", "امروز، اولیس به‌عنوان یکی از بزرگ‌ترین آثار ادبیات نوشته‌شده شناخته می‌شود و ۱۶ ژوئن در سراسر جهان به‌عنوان روز بلوم جشن گرفته می‌شود."),
            StoryParagraph("On that day, people gather to read the novel aloud, to walk the streets of Dublin that Bloom walked, to celebrate the ordinary and the extraordinary.", "در آن روز، مردم جمع می‌شوند تا رمان را بلند بخوانند، در خیابان‌های دوبلینی که بلوم پیمود قدم بزنند، معمولی و فوق‌العاده را جشن بگیرند."),
            StoryParagraph("And so Ulysses, once banned, once mocked, once dismissed, has become a part of our common heritage, a part of what makes us human.", "و اینگونه اولیس، زمانی ممنوع، زمانی مسخره، زمانی ردشده، بخشی از میراث مشترک ما شده، بخشی از آنچه ما را انسان می‌کند."),
            StoryParagraph("The novel's message is complex, but its heart is simple: life is worth living, love is worth giving, the ordinary is worth celebrating.", "پیام رمان پیچیده است اما قلبش ساده: زندگی ارزش زیستن دارد، عشق ارزش دادن دارد، معمولی ارزش جشن گرفتن."),
            StoryParagraph("Bloom is not a hero, but he is a good man; and goodness, Joyce suggests, is more valuable than heroism.", "بلوم قهرمان نیست اما مرد خوبی است؛ و خوبی، جویس پیشنهاد می‌دهد، از قهرمانی ارزشمندتر است."),
            StoryParagraph("Bloom is not a saint, but he is kind; and kindness, Joyce suggests, is more valuable than sanctity.", "بلوم قدیس نیست اما مهربان است؛ و مهربانی، جویس پیشنهاد می‌دهد، از تقدس ارزشمندتر است."),
            StoryParagraph("Bloom is not wise, but he endures; and endurance, Joyce suggests, is more valuable than wisdom.", "بلوم فرزانه نیست اما تحمل می‌کند؛ و تحمل، جویس پیشنهاد می‌دهد، از خرد ارزشمندتر است."),
            StoryParagraph("Bloom is not happy, but he is alive; and life, Joyce suggests, is the only thing that matters in the end.", "بلوم خوشحال نیست اما زنده است؛ و زندگی، جویس پیشنهاد می‌دهد، تنها چیزی است که در پایان اهمیت دارد."),
            StoryParagraph("And Molly, in her final yes, says yes to all of it: to life, to love, to suffering, to joy, to the whole great mystery of being.", "و مالی، در بله نهایی‌اش، به همه‌اش بله می‌گوید: به زندگی، به عشق، به رنج، به شادی، به تمام رمز بزرگ بودن."),
            StoryParagraph("Her yes is the yes of the novel itself, the yes of Joyce, the yes of every human being who has ever chosen to live fully, to love deeply, to endure bravely.", "بله او بله خود رمان است، بله جویس، بله هر انسانی که هرگز انتخاب کرده کامل زندگی کند، عمیق عشق بورزد، شجاعانه تحمل کند."),
            StoryParagraph("And that yes, that great, life-affirming yes, is what makes Ulysses not just a great novel but a great gift to humanity.", "و آن بله، آن بله بزرگ و زندگی‌ستا، همان چیزی است که اولیس را نه تنها رمانی بزرگ بلکه هدیه‌ای بزرگ به بشریت می‌کند."),
            StoryParagraph("For in a world of suffering, in a world of confusion, in a world of darkness, the only true rebellion is to say yes.", "زیرا در جهانی از رنج، در جهانی از گیجی، در جهانی از تاریکی، تنها شورش راستین بله گفتن است."),
            StoryParagraph("Yes to life. Yes to love. Yes to everything.", "بله به زندگی. بله به عشق. بله به همه چیز."),
            StoryParagraph("And so ends Ulysses, and so begins a new understanding of what literature can be, what life can be, what we can be.", "و اینگونه اولیس پایان می‌یابد و اینگونه فهمی نو آغاز می‌شود از آنچه ادبیات می‌تواند باشد، زندگی می‌تواند باشد، ما می‌توانیم باشیم."),
            StoryParagraph("Joyce wrote the novel to celebrate the ordinary man, the ordinary day, the ordinary city.", "جویس رمان را نوشت تا مرد معمولی را جشن بگیرد، روز معمولی، شهر معمولی."),
            StoryParagraph("And in doing so, he showed us that nothing is ordinary, that everything is extraordinary, that the smallest detail contains the whole universe.", "و در این کار، نشانمان داد هیچ چیز معمولی نیست، همه چیز فوق‌العاده است، کوچک‌ترین جزئیات تمام جهان را در خود دارد."),
            StoryParagraph("This is the deepest wisdom of the novel: to see the infinite in the finite, the eternal in the moment, the sacred in the profane.", "این عمیق‌ترین خرد رمان است: دیدن بی‌نهایت در متناهی، ابدی در لحظه، مقدس در نامقدس."),
            StoryParagraph("And to say yes to all of it, with all our heart, with all our soul, with all our being.", "و بله گفتن به همه‌اش، با تمام قلبمان، با تمام روحمان، با تمام وجودمان."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("Yes. Yes. Yes.", "بله. بله. بله.")
        )
    )
}